import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanner.Scan()
	n := 0
	fmt.Sscanf(scanner.Text(), "%d", &n)

	cubes := make([]map[int]bool, n)
	notz := false
	for i := 0; i < n; i++ {
		cubes[i] = make(map[int]bool)
		for j := 0; j < 6; j++ {
			scanner.Scan()
			cur := 0
			fmt.Sscanf(scanner.Text(), "%d", &cur)
			if cur != 0 {
				notz = true
			}
			cubes[i][cur] = true
		}
	}

	if !notz {
		fmt.Println(0)
	} else {
		for i := 1; i <= 1001; i++ {
			if i == 1000 || !aux(cubes, i) {
				fmt.Println(i - 1)
				break
			}
		}
	}
}

