	hun := 0
	if num/100 > 0 {
		hun = num / 100
	} else {
		hun = -1 // null equivalent
	}

	ten := 0
	if (num%100)/10 > 0 {
		ten = (num % 100) / 10
	} else {
		ten = -1 // null equivalent
	}

	one := num % 10

	// Helper to check presence
	has := func(cubeIdx int, digit int) bool {
		if cubeIdx < 0 || cubeIdx >= len(pos) {
			return false
		}
		_, ok := pos[cubeIdx][digit]
		return ok
	}

	if ten == -1 && hun == -1 {
		return has(0, one) || has(1, one) || has(2, one)
	}

	if hun == -1 {
		return (has(0, one) && (has(1, ten) || has(2, ten))) ||
			(has(1, one) && (has(0, ten) || has(2, ten))) ||
			(has(2, one) && (has(0, ten) || has(1, ten)))
	}

	return (has(0, one) && has(1, ten) && has(2, hun)) ||
		(has(1, one) && has(0, ten) && has(2, hun)) ||
		(has(0, one) && has(2, ten) && has(1, hun)) ||
		(has(1, one) && has(2, ten) && has(0, hun)) ||
		(has(2, one) && has(1, ten) && has(0, hun)) ||
		(has(2, one) && has(0, ten) && has(1, hun))
}

